{:else}
  <header class="studio-heading"><div class="studio-breadcrumb"><a href="/studio">Planungsstudio</a><span>/</span><span>{snapshot.kind==='memorial'?'Grabmal':'Raum & Naturstein'}</span></div><div class="studio-title-row"><div><h1>{data.detail.name??data.detail.title??'Planung'}</h1><p><span class="sync-dot" class:unsaved={pending.length>0} class:has-conflict={!!conflict}></span>{syncLabel}{lastSaved&&!pending.length?` · ${lastSaved}`:''}<span class="revision-chip">Revision {sourceRevision?.revision_number??sourceRevision?.version??baseVersion}</span></p></div><div class="heading-actions"><button class="btn" onclick={()=>{sourceReferenceId='';sourcePlanOpen=true;}}><Icon name="file" size={15}/>Quellplan / Foto</button><button class="btn" onclick={()=>showBom=!showBom}><Icon name="file" size={16}/>Stückliste</button><button class="btn" onclick={()=>exportPlan('pdf')} disabled={saving||!!conflict}><Icon name="download" size={16}/>Planungs-PDF</button><button class="btn primary" onclick={()=>save()} disabled={saving||!pending.length||!!conflict||isHistoric}><Icon name="check" size={16}/>{saving?'Speichert …':'Speichern'}</button></div></div></header>
