3d'}/>Raster</label><button class="fit-button" onclick={fit}>Einpassen</button><button class="panel-toggle" aria-label="Eigenschaften ein- oder ausblenden" onclick={()=>rightPanel=!rightPanel}><Icon name="settings" size={16}/></button></div>
