kind==='memorial'?[['stone_piece','Stein / Sockel'],['inscription','Inschrift'],['grave_border','Einfassung'],['catalog_object','Zubehör'],['group','Gruppe'],['technical_note','Hinweis']]:[['room','Raum'],['wall','Wand'],['opening','Tür / Fenster'],['stone_piece','Steinbauteil'],['surface','Belagsfläche'],['catalog_object','Produkt'],['connection','Anschluss'],['machining','Bearbeitung'],['clearance','Freifläche'],['slope','Gefälle'],['group','Gruppe'],['technical_note','Hinweis']] as [kind,name]}<button onclick={()=>addKind=kind} disabled={!canEdit||isHistoric}><Icon name="plus" size={13}/>{name}</button>{/each}</div></div></aside>{/if}
