        {#if snapMarker}<g class="snap-marker" pointer-events="none" aria-hidden="true"><circle cx={snapMarker.point.xMm} cy={-Number(snapMarker.point.yMm)} r={snapMarker.radius} fill="#fff" stroke="#315c4c" stroke-width="2" vector-effect="non-scaling-stroke"/><path d={`M${Number(snapMarker.point.xMm)-snapMarker.radius*1.5} ${-Number(snapMarker.point.yMm)}h${snapMarker.radius*3}M${snapMarker.point.xMm} ${-Number(snapMarker.point.yMm)-snapMarker.radius*1.5}v${snapMarker.radius*3}`} fill="none" stroke="#315c4c" stroke-width="1.5" vector-effect="non-scaling-stroke"/></g>{/if}
      </svg>
      {#if !snapshot.elements.length}<div class="canvas-empty"><div class="plan-mark"><Icon name={snapshot.kind==='memorial'?'pen':'box'} size={30}/></div><h3>{snapshot.kind==='memorial'?'Raum für Erinnerung.':'Der erste Strich für Ihren Raum.'}</h3><p>{snapshot.kind==='memorial'?'Legen Sie Steinform und Auftragsmaße fest. Inschriften und Material ergänzen Sie anschließend.':'Beginnen Sie mit einem bemaßten Raum oder ergänzen Sie Bauteile einzeln.'}</p><button class="btn primary" onclick={()=>addKind=snapshot!.kind==='memorial'?'stone_piece':'room'} disabled={!canEdit}><Icon name="plus" size={16}/>{snapshot.kind==='memorial'?'Ersten Stein anlegen':'Raum anlegen'}</button></div>{/if}
      {/if}
      <div class="canvas-bottom"><span>{snapLabel||`${selectedIds.length?`${selectedIds.length} ausgewählt`:`${snapshot.elements.length} Elemente`} · ${mode==='move'?'Verschieben':mode==='pan'?'Ansicht verschieben':'Auswahl'}`}</span><div><button aria-label="Verkleinern" onclick={()=>changeZoom(false)}>−</button><span>{Math.round((view==='3d'?threeZoom:zoom)*100)} %</span><button aria-label="Vergrößern" onclick={()=>changeZoom(true)}>+</button></div></div>
      <div class="canvas-disclaimer">{snapshot.kind==='memorial'?'Schriftmarker verweisen auf die unveränderte Textprüfung. Herstellerbilder sind keine Fertigungskonturen.':'Planmaße und Aufmaß werden getrennt geführt. Katalogobjekte ohne Originaldaten sind vereinfacht.'}</div>
    </section>
    {#if rightPanel}<aside class="inspector"><nav aria-label="Eigenschaftenbereiche"><button class:active={tab==='properties'} onclick={()=>tab='properties'}>Eigenschaften</button><button class:active={tab==='checks'} onclick={()=>tab='checks'}>Prüfen</button><button class:active={tab==='versions'||tab==='compare'} onclick={()=>tab='versions'}>Stände</button></nav>
      {#if tab==='properties'}{#if selected}<div class="inspector-body"><p class="inspector-eyebrow">{kindLabels[selected.kind]}{selected.phase==='existing'?' · BESTAND':''}</p><h2>{selected.label}</h2>{#if selectedIds.length>1}<p class="field-hint">{selectedIds.length} Elemente ausgewählt. Gemeinsame Aktionen betreffen die gesamte Auswahl; Einzelangaben unten gelten für {selected.label}.</p>{/if}{#if selectedIds.length>1||selected.kind==='room'}<SelectionMoveEditor snapshot={activeSnapshot!} {selectedIds} disabled={!canEdit||isHistoric||selectedElements.some(e=>e.locked)} onchange={edit}/>{/if}{#if selected.locked}<div class="inspector-info"><Icon name="lock" size={15}/>Dieses Element ist gesperrt.{selected.kind==='inscription'?' Bestehende Schrift bleibt geschützt.':''}</div>{/if}
        <fieldset disabled={!canEdit||isHistoric||selected.locked}>{#if selected.kind!=='inscription'}<label class="inspector-label">Planungsphase<select value={selected.phase} onchange={event=>edit([{type:'set_element_phase',elementId:selected!.id,phase:event.currentTarget.value as DesignElement['phase']}])}><option value="planned">Geplant</option><option value="existing">Bestand</option><option value="demolition">Rückbau</option></select></label>{/if}<label class="inspector-label">Bezeichnung<input value={selected.label} onchange={(event)=>edit([{type:'rename_element',elementId:selected!.id,label:event.currentTarget.value}])}/></label>
          {#if 'transform'in selected||'point'in selected}{@const position='transform'in selected?selected.transform.position:'point'in selected?selected.point:null}{#if position}<div class="inspector-section"><h3>Position</h3><div class="xyz-fields">{#each [['xMm','X'],['yMm','Y'],['zMm','Z']] as [axis,name]}<label>{name}<input inputmode="decimal" value={position[axis as keyof Point3]} onchange={(event)=>changePosition(axis as keyof Point3,event.currentTarget.value)}/></label>{/each}</div><p class="field-hint">Lokaler Bezug: {activeSnapshot!.elements.find(e=>e.id===selected!.parentId)?.label??activeSnapshot!.frames.find(f=>f.id===selected!.parentId)?.datumLabel??'Planursprung'} · mm</p></div>{/if}{/if}
          {#if 'transform'in selected}<label class="inspector-label">Drehung um Z (Grad)<input inputmode="decimal" value={selected.transform.rotationDeg.z} onchange={(event)=>{const n=event.currentTarget.value.replace(',','.');if(/^-?\d+(?:\.\d+)?$/.test(n)&&selected&&'transform'in selected)edit([{type:'rotate_element',elementId:selected.id,rotationDeg:{...selected.transform.rotationDeg,z:n}}]);}}/></label>{/if}
          {#if selected.kind==='dimension'}<div class="inspector-section"><h3>Bauteilmaß und Quellenbezug</h3><MeasurementField snapshot={activeSnapshot!} measureId={selected.measureId} label={selected.label} elementId={selected.id} field="measureId" evidence={data.related?.documents??[]} onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/><p class="field-hint">{selected.mode==='reference'?'Dieses Referenzmaß stammt aus der Geometrie.':'Ein treibendes Maß bindet die zugeordneten Bauteilbezüge.'}</p></div>{/if}{#if selected.kind==='plan_reference'}<div class="inspector-section"><h3>Versionierter Quellplan</h3><p class="field-hint">Seite {selected.pageIndex+1} · {selected.sourceKind} · {selected.sourceHash.slice(0,16)}…</p><button class="btn small" onclick={()=>{sourceReferenceId=selected.id;sourcePlanOpen=true;}}>Quelle und Kalibrierung öffnen</button></div>{/if}{#if selected.kind==='stone_piece'}<div class="inspector-section"><h3>Außenmaße & Material</h3>{#each activeSnapshot!.elements.filter(e=>e.kind==='dimension'&&e.mode==='driving'&&e.refs.some(r=>r.elementId===selected!.id)) as dim}{#if dim.kind==='dimension'}<MeasurementField snapshot={activeSnapshot!} measureId={dim.measureId} label={dim.label} elementId={dim.id} field="measureId" evidence={data.related?.documents??[]} onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/>{/if}{/each}<MeasurementField snapshot={activeSnapshot!} measureId={selected.thicknessMeasureId} label="Materialstärke" elementId={selected.id} field="thicknessMeasureId" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} evidence={data.related?.documents??[]} disabled={!canEdit||isHistoric}/><label class="inspector-label" for="stone-material">Materialstand</label><ReferencePicker id="stone-material" reference="material-versions" initial={materials} value={selected.materialSpecVersionId.startsWith('unassigned')?'':selected.materialSpecVersionId} onchange={value=>edit([{type:'set_stone_spec',elementId:selected!.id,materialSpecVersionId:value||'unassigned:material'}])}/><label class="inspector-label">Maserungsrichtung (Grad)<input inputmode="decimal" value={selected.grainDirectionDeg??''} onchange={(event)=>edit([{type:'set_stone_spec',elementId:selected!.id,grainDirectionDeg:event.currentTarget.value?event.currentTarget.value.replace(',','.'):null}])}/></label><label class="inspector-label">Rohplatte / Charge<select value={selected.stockItemId??''} onchange={(event)=>edit([{type:'set_stone_spec',elementId:selected!.id,stockItemId:event.currentTarget.value||null}])}><option value="">Nicht zugeordnet</option>{#each stockItems as stock}<option value={stock.id}>{stock.name}</option>{/each}</select></label><h3>Kantenbearbeitung</h3>{#key selected.id}<EdgeTreatmentEditor stone={selected} treatments={edgeTreatments} onchange={edit}/>{/key}<div class="inspector-actions"><button class="btn small" onclick={()=>addKind='machining'}>Ausschnitt / Bearbeitung ergänzen</button>{#if snapshot.kind==='memorial'}<button class="btn small" onclick={()=>addKind='inscription'}>Inschrift ergänzen</button>{/if}</div></div>{/if}
          {#if selected.kind==='inscription'}<div class="inspector-section"><h3>Wörtlicher Inhalt</h3><label class="inspector-label">Originaltext<textarea rows="5" value={selected.exactText} onchange={(event)=>edit([{type:'set_inscription_text',elementId:selected!.id,exactText:event.currentTarget.value}])}></textarea></label><p class="field-hint">Namen, Daten und Sonderzeichen werden unverändert gespeichert. Keine automatische Großschreibung.</p><label class="inspector-label">Herstellerschrift<select value={selected.fontVariantVersionId} onchange={(event)=>changeFont(event.currentTarget.value)}>{#each fonts as entry}<option value={entry.version_id??entry.id}>{entry.name} · {entry.selection_ref} · {entry.supply_form==='wording'?'Schriftzug':'Einzelbuchstaben'}</option>{/each}</select></label>{#if font&&imageUrl(font)}<figure class="font-reference"><img src={imageUrl(font)!} alt={`Originale Strassacker-Bildreferenz ${font.name} ${font.selection_ref}`} loading="lazy" referrerpolicy="no-referrer"/><figcaption>{font.name} · Auswahl {font.selection_ref}<br/>Originalbild · {font.thumbnail_material==='bronze'?'Bronze':font.thumbnail_material==='aluminium'?'Aluminium':font.thumbnail_material??'Quellmaterial'} · Bildreferenz</figcaption></figure>{/if}<p class="font-warning">Keine belegten Zeichenbreiten oder Bohrpunkte. Benötigte Glyphen und der Satz werden vom Lieferanten bestätigt.</p><MeasurementField snapshot={activeSnapshot!} measureId={selected.requestedHeightMeasureId} label="Gewünschte Zeichenhöhe" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/><MeasurementField snapshot={activeSnapshot!} measureId={selected.requestedMaxWidthMeasureId} label="Maximale Schriftbreite" elementId={selected.id} field="requestedMaxWidthMeasureId" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/><MeasurementField snapshot={activeSnapshot!} measureId={selected.requestedLowercaseHeightMeasureId} label="Gewünschte Kleinbuchstabenhöhe" elementId={selected.id} field="requestedLowercaseHeightMeasureId" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/><MeasurementField snapshot={activeSnapshot!} measureId={selected.lineGapMeasureId} label="Zeilenabstand" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} disabled={!canEdit||isHistoric}/><div class="xyz-fields two"><label>u (mm)<input inputmode="decimal" value={selected.originUV.uMm} onchange={(e)=>changeUV('uMm',e.currentTarget.value)}/></label><label>v (mm)<input inputmode="decimal" value={selected.originUV.vMm} onchange={(e)=>changeUV('vMm',e.currentTarget.value)}/></label></div><label class="inspector-label">Ausrichtung<select value={selected.alignment} onchange={(event)=>edit([{type:'set_inscription_layout',elementId:selected!.id,alignment:event.currentTarget.value as any}])}><option value="left">Links</option><option value="center">Zentriert</option><option value="right">Rechts</option></select></label><label class="inspector-label">Belegte Materialausführung<select value={selected.materialArticleReference??''} onchange={(event)=>edit([{type:'set_inscription_layout',elementId:selected!.id,materialArticleReference:event.currentTarget.value||null}])}><option value="">Ausführung noch offen</option>{#each fontArticles as article}<option value={article.value}>{article.label}</option>{/each}</select></label><label class="inspector-label" for="inscription-material">Konkreter Materialstand</label><ReferencePicker id="inscription-material" reference="material-versions" initial={materials} value={selected.materialSpecVersionId??''} onchange={value=>edit([{type:'set_inscription_layout',elementId:selected!.id,materialSpecVersionId:value||null}])}/><label class="inspector-label">Bestätigtes Finish<select value={selected.finishSpecVersionId??''} onchange={(event)=>edit([{type:'set_inscription_layout',elementId:selected!.id,finishSpecVersionId:event.currentTarget.value||null}])}><option value="">Noch nicht festgelegt</option>{#each finishes as finish}<option value={finish.id}>{finish.name}</option>{/each}</select></label><p class="field-hint">Nutzungsrechte und Variantenverträglichkeit müssen aus den zugehörigen Herstellerunterlagen hervorgehen.</p><a class="text-button" href="/glyph-library">Originaldaten & Befestigung verwalten</a><button class="btn small" disabled={isHistoric||selected.phase==='existing'&&!canRelease} onclick={()=>glyphLayoutOpen=true}>Geprüfte Originalzeichen zuordnen</button>{#if font?.material_references}<p class="field-hint">Belegte Quellreferenzen: {Object.entries(font.material_references).map(([key,value])=>`${key}: ${Array.isArray(value)?value.join(', '):value}`).join(' · ')}</p>{/if}</div>{/if}
          {#if selected.kind==='wall'}<div class="inspector-section"><h3>Wandaufbau</h3><MeasurementField snapshot={activeSnapshot!} measureId={selected.heightMeasureId} label="Wandhöhe" elementId={selected.id} field="heightMeasureId" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} evidence={data.related?.documents??[]} disabled={!canEdit||isHistoric}/><MeasurementField snapshot={activeSnapshot!} measureId={selected.coreThicknessMeasureId} label="Kernstärke" elementId={selected.id} field="coreThicknessMeasureId" onchange={edit} actorId={data.user?.id??''} canConfirm={canRelease} evidence={data.related?.documents??[]} disabled={!canEdit||isHistoric}/><button class="btn small" onclick={()=>addKind='opening'}>Tür / Fenster ergänzen</button><p class="field-hint">Die Lage entsteht aus Anfangs- und Endknoten. Gemeinsame Wände werden einmal geführt.</p></div>{/if}
