        {:else}<div class="inspector-empty"><Icon name="pen" size={28}/><h3>Im Detail gestalten.</h3><p>Wählen Sie ein Element im Plan oder in der Liste. Hier bearbeiten Sie Maße, Material und Ausführung.</p><p class="small">Alle Drag-Aktionen sind auch über Zahlenfelder möglich.</p></div>{/if}
      {:else if tab==='checks'}<div class="inspector-body"><p class="inspector-eyebrow">VOR DER AUSFÜHRUNG</p><h2>Prüfstand</h2><p class="field-hint">{releaseValidation.blocking.length} Punkte verhindern derzeit eine technische Freigabe. Der Entwurf bleibt bearbeitbar.</p>{#each releaseValidation.blocking as issue}<div class="check-item"><Icon name="alert" size={15}/><div><p>{describeStudioIssue(activeSnapshot,issue).message}</p>{#if describeStudioIssue(activeSnapshot,issue).elementId}<button class="text-button" onclick={()=>repairIssue(issue)}>{describeStudioIssue(activeSnapshot,issue).fieldLabel??'Bauteil'} öffnen</button>{/if}</div></div>{/each}{#each releaseValidation.warnings as issue}<div class="check-item neutral"><Icon name="help" size={15}/><div><p>{describeStudioIssue(activeSnapshot,issue).message}</p>{#if describeStudioIssue(activeSnapshot,issue).elementId}<button class="text-button" onclick={()=>repairIssue(issue)}>{describeStudioIssue(activeSnapshot,issue).fieldLabel??'Bauteil'} öffnen</button>{/if}</div></div>{/each}<div class="inspector-section"><h3>Freigaben sind getrennt</h3><p class="field-hint">Kundenbestätigung von Text oder Gestaltung ersetzt keine technische Fachprüfung oder Genehmigung.</p><button class="btn small" onclick={()=>approvalOpen=!approvalOpen} disabled={isHistoric}>Zustimmung dokumentieren</button>{#if approvalOpen}<form class="approval-form" onsubmit={approve}><label class="inspector-label">Art<select bind:value={approvalKind}><option value="design">Gestaltung</option><option value="inscription">Wörtliche Inschrift</option><option value="technical">Technische Prüfung</option></select></label><label class="inspector-label">Konkrete Erklärung<textarea bind:value={statement} required rows="4" placeholder="Prüfumfang und Nachweis für genau diese Revision"></textarea></label><button class="btn small primary" type="submit">An diese Revision binden</button></form>{/if}</div><div class="inspector-section"><button class="btn small" onclick={()=>releaseOpen=!releaseOpen} disabled={!canRelease||releaseValidation.blocking.length>0||isHistoric}>Fertigungsfreigabe vorbereiten</button>{#if releaseOpen}<form onsubmit={release}><label class="inspector-label">Fachlicher Freigabegrund<textarea bind:value={releaseReason} required rows="3"></textarea></label><p class="font-warning">Fertigung erst mit vollständig geprüftem Paket. Diese Aktion ist verbindlich und wird serverseitig autorisiert.</p><button class="btn small primary" type="submit">Diese Revision zur Fertigung freigeben</button></form>{/if}</div><div class="inspector-section"><ReleasePackages packages={data.related?.release_packages??[]} revisionId={baseRevisionId}/><h3>Bild & Unterlagen</h3><button class="btn small" onclick={openVisualization} disabled={!canEdit||isHistoric}>KI-Konzeptbild erstellen</button><button class="btn small" onclick={openComposite} disabled={!canEdit||isHistoric}>Konzeptbild mit geschütztem Bestand</button><label class="inspector-label">Bildqualität<select bind:value={renderProfile}><option value="preview">Kundenansicht · 1440 × 1080</option><option value="final">Finale Ansicht · 3840 × 2880</option></select></label><button class="btn small" onclick={requestRender} disabled={isHistoric||renderRequestBusy}>{renderRequestBusy?'Wird angefordert …':'Renderauftrag anfordern'}</button><button class="btn small" onclick={refreshRenderStatus} disabled={renderStatusBusy}>{renderStatusBusy?'Wird aktualisiert …':'Renderstatus aktualisieren'}</button>{#each renderJobs as job}<div class="render-record"><strong>{job.profile==='concept'?'Geschütztes Konzeptbild':job.profile==='final'?'Finale Ansicht':'Kundenansicht'}</strong><span>{job.status==='completed'?'Fertig':job.status==='running'?'Wird berechnet':job.status==='pending'?'Wartet':job.status==='unavailable'?'Dienst fehlt':job.status==='failed'?'Prüfung erforderlich':job.status}</span><small>{job.revision_id===baseRevisionId?'Aktueller Planstand':'Früherer Planstand'}</small>{#if job.last_error}<p>{job.last_error}</p>{/if}</div>{/each}{#each renderArtifacts as artifact}<a data-sveltekit-reload class="render-record" href={`/api/v1/documents/${artifact.document_id}/download${artifact.document_version_id?'?version='+artifact.document_version_id:''}`} target="_blank" rel="noreferrer"><strong>Gespeicherte Ansicht · {artifact.width_px} × {artifact.height_px} px</strong><small>{artifact.revision_id===baseRevisionId?'Aktueller Planstand':'Früherer Planstand'} · {artifact.kind==='protected_composite'?'Konzept · Originalpixel geschützt':artifact.accuracy==='verified_geometry'?'Geprüfte Plangeometrie':'Modelldarstellung'}</small></a>{/each}<p class="field-hint">Render benötigt einen eingerichteten Worker. Ein generiertes Bild ist keine technische Zeichnung.</p><div class="inspector-actions"><button class="btn small" onclick={()=>exportPlan('svg')}>SVG</button><button class="btn small" onclick={()=>exportPlan('bom')}>Stückliste exportieren</button></div></div></div>
      {:else if tab==='compare'}{@const other=comparison()}<div class="inspector-body"><p class="inspector-eyebrow">NEBENEINANDER BEWERTEN</p><h2>Variantenvergleich</h2><label class="inspector-label">Vergleichsstand<select bind:value={compareId}><option value="">Variante auswählen</option>{#each variants.filter((v:any)=>v.id!==snapshot!.variantId) as v}<option value={v.id}>{v.name}</option>{/each}</select></label>{#if other&&bom}<table class="compare-table"><thead><tr><th>Merkmal</th><th>Aktuell</th><th>Vergleich</th></tr></thead><tbody><tr><td>Bauteile</td><td>{bom.totals.pieces}</td><td>{other.totals.pieces}</td></tr><tr><td>Netto Stein (m²)</td><td>{bom.totals.stoneNetAreaM2}</td><td>{other.totals.stoneNetAreaM2}</td></tr><tr><td>Bearb. Kante (m)</td><td>{bom.totals.treatedEdgeLengthM}</td><td>{other.totals.treatedEdgeLengthM}</td></tr><tr><td>Produktpositionen</td><td>{bom.lines.filter(l=>l.category==='Katalogartikel').length}</td><td>{other.lines.filter(l=>l.category==='Katalogartikel').length}</td></tr><tr><td>Prüfpunkte</td><td>{bom.validation.warnings.length}</td><td>{other.validation.warnings.length}</td></tr></tbody></table>{#if comparedSnapshot}<ComparisonDetails current={activeSnapshot!} other={comparedSnapshot} currentName={historical?.name??sourceRevision?.name??variant?.name??'Aktueller Stand'} otherName={variants.find((v:any)=>v.id===compareId)?.name??'Vergleichsstand'} approvals={data.related?.approvals??[]} library={[...products,...materials,...fonts,...finishes]} onselect={id=>{selectedIds=[id];tab='properties';}}/>{/if}<p class="field-hint">Kosten entstehen aus freigegebenen Preisständen der Kalkulation. Für fehlende Preise wird keine Summe erfunden.</p>{:else}<p class="field-hint">Wählen Sie eine weitere Variante mit geladenem Revisionsstand.</p>{/if}</div>
      {:else}<div class="inspector-body"><p class="inspector-eyebrow">NACHVOLLZIEHBARE STÄNDE</p><h2>Varianten & Revisionen</h2><label class="inspector-label">Neue Variante<input bind:value={variantName} placeholder="Zum Beispiel Heller Naturstein"/></label><button class="btn small primary" onclick={()=>createVariant(historicalId||baseRevisionId)} disabled={!canEdit}>Aus diesem Stand anlegen</button><form class="inspector-section" onsubmit={nameRevision}><h3>Aktuellen Stand benennen</h3><label class="inspector-label">Revisionsbezeichnung<input bind:value={revisionName} maxlength="150" required placeholder="Zum Beispiel Abstimmung vom 17. Oktober" disabled={!canEdit||isHistoric||saving}/></label><button class="btn small" type="submit" disabled={!canEdit||isHistoric||saving||!revisionName.trim()}>Als benannte Revision speichern</button><p class="field-hint">Speichert einen neuen unveränderlichen Planstand. Freigaben bleiben an der jeweils geprüften ursprünglichen Revision.</p></form><div class="inspector-section"><h3>Gespeicherte Revisionen</h3>{#each revisions.filter((r:any)=>r.variant_id===snapshot!.variantId) as revision}<button class="revision-row" class:active={(historicalId||baseRevisionId)===revision.id} onclick={()=>historicalId=revision.id===baseRevisionId?'':revision.id}><strong>{revision.name??revision.label??`Revision ${revision.revision_number??revision.version??revision.id.slice(0,8)}`}</strong><small>{revision.created_at?new Date(revision.created_at).toLocaleString('de-DE'):'Unveränderlicher Planstand'}</small></button>{/each}</div><label class="inspector-label">Rasterweite (mm)<input bind:value={gridSize} inputmode="decimal"/></label><p class="field-hint">Fangradius: 8 Bildschirmpixel. Zoom ändert keine realen Maße.</p></div>{/if}
    </aside>{/if}
  </div>
  {#if activeSnapshot!.elements.some(e=>e.kind==='inscription')}<section class="literal-preview"><header><div><p>WÖRTLICHE TEXTPRÜFUNG</p><h2>Namen. Daten. Jedes Zeichen.</h2></div><span>Leseschrift zur Prüfung · keine Herstellerkontur</span></header><div class="literal-groups">{#each activeSnapshot!.elements.filter(e=>e.kind==='inscription') as inscription,index}{#if inscription.kind==='inscription'}<article class:selected={selectedIds.includes(inscription.id)}><button aria-label={`${inscription.label} im Plan auswählen`} onclick={()=>{selectedIds=[inscription.id];tab='properties';rightPanel=true;}}><span>{index+1}</span>{inscription.label}{#if inscription.locked}<Icon name="lock" size={13}/>{/if}</button><p>{inscription.exactText}</p><small>Höhe {measureValue(activeSnapshot!,inscription.requestedHeightMeasureId)??'offen'} mm · Max. Breite {measureValue(activeSnapshot!,inscription.requestedMaxWidthMeasureId)??'offen'} mm</small></article>{/if}{/each}</div></section>{/if}
  {#if showBom&&bom}<section class="bom-panel"><header><div><p>GENAU DIESER PLANSTAND</p><h2>Stück- und Bearbeitungsliste</h2></div><button class="btn small" onclick={()=>exportPlan('bom')}><Icon name="download" size={15}/>Exportieren</button></header><div class="bom-scroll"><table><thead><tr><th>Bauteil</th><th>Ausführung</th><th>Menge</th><th>Nettofläche</th><th>Stärke</th><th>Kante</th></tr></thead><tbody>{#each bom.lines as line}<tr><td><button onclick={()=>{selectedIds=[line.elementId];rightPanel=true;tab='properties';}}>{line.label}</button></td><td>{line.category}</td><td>{line.quantity} {line.unit}</td><td>{line.netAreaM2===null?'—':`${line.netAreaM2} m²`}</td><td>{line.thicknessMm===null?'Offen':`${line.thicknessMm} mm`}</td><td>{line.edgeLengthM===null?'—':`${line.edgeLengthM} m`}</td></tr>{/each}</tbody></table></div><footer>Kein pauschaler Verschnitt oder Gewicht ohne bestätigte Regel. {bom.totals.unresolvedVolumeCount} Bauteile mit ungeklärtem Volumen.</footer></section>{/if}
  {#if addKind}<AddElementDialog kind={addKind} {snapshot} {data} selectedId={selectedIds[0]??null} onclose={()=>addKind=''} onadd={(ops,id)=>{applyBatch(ops,id);addKind='';}}/>{/if}
{/if}
</div>

{#if glyphLayoutOpen&&selected?.kind==='inscription'&&activeSnapshot}<GlyphLayoutDialog inscription={selected} snapshot={activeSnapshot} glyphs={data.related?.glyphs??[]} evidence={data.related?.documents??[]} onsubmit={edit} onclose={()=>glyphLayoutOpen=false}/>{/if}
{#if sourcePlanOpen&&activeSnapshot}<SourcePlanDialog snapshot={activeSnapshot} documents={data.related?.documents??[]} referenceId={sourceReferenceId} disabled={!canEdit||isHistoric} onapply={(ops,id)=>{try{applyBatch(ops,id);}catch(problem){error=(problem as Error).message;throw problem;}}} onclose={()=>sourcePlanOpen=false}/>{/if}
{#if constraintOpen&&activeSnapshot}<ConstraintDialog snapshot={activeSnapshot} selectedId={selectedIds[0]??''} rules={data.related?.rules??[]} disabled={!canEdit||isHistoric} onapply={ops=>applyBatch(ops)} onclose={()=>constraintOpen=false}/>{/if}
{#if visualizationOpen}<VisualizationDialog {data} revisionId={baseRevisionId} jobs={data.related?.ai_visualizations??[]} onclose={()=>visualizationOpen=false}/>{/if}
{#if compositeOpen}<CompositeDialog revisionId={baseRevisionId} jobs={renderJobs} documents={data.related?.documents??[]} onclose={()=>compositeOpen=false}/>{/if}
